+func (d *DB) onBatchSyncComplete(b *Batch, err error) {
+	if d.opts.DisableWAL || !b.syncWAL {
+		return
+	}
+	var seqNum base.SeqNum
+	if len(b.data) > 0 {
+		seqNum = b.SeqNum()
+	} else if b.flushable != nil {
+		seqNum = b.flushable.seqNum
+	}
+	endSeqNum := seqNum
+	if b.savedKeyCount > 0 {
+		endSeqNum = seqNum + base.SeqNum(b.savedKeyCount) - 1
+	}
+	d.durability.recordCommitOutcome(b.durableJobID, endSeqNum, b.syncDuration, err)
+	if d.opts.EventListener != nil && d.opts.EventListener.BatchDurable != nil {
+		d.opts.EventListener.BatchDurable(BatchDurableInfo{
+			JobID:         b.durableJobID,
+			SeqNum:        endSeqNum,
+			Err:           err,
+			ApplyDuration: b.applyDuration,
+			SyncDuration:  b.syncDuration,
+			CorrelationID: b.correlationID,
+			BatchSize:     b.savedBatchSize,
+			KeyCount:      b.savedKeyCount,
+		})
+	}
+}
